                                const std::uint32_t events) {
    SetFileDescriptor(Control::Add, fd, events);
}

void Epoller::DeleteFileDescriptor(const ws::FileDescriptor fd) {
    SetFileDescriptor(Control::Delete, fd);
}

void Epoller::ModifyFileDescriptor(const ws::FileDescriptor fd,
                                   const std::uint32_t events) {
    SetFileDescriptor(Control::Modify, fd, events);
}

void Epoller::SetFileDescriptor(const Control ctl, const ws::FileDescriptor fd,
                                const std::optional<std::uint32_t> events) {
    static const std::unordered_map<Control, int> op_codes {
        {Control::Add, EPOLL_CTL_ADD},
        {Control::Delete, EPOLL_CTL_DEL},
        {Control::Modify, EPOLL_CTL_MOD},
    };

    assert(IsValidFileDescriptor(fd));
    assert(op_codes.contains(ctl));

    epoll_event event {};
    event.data.fd = fd;
    if (ctl != Control::Delete) {
        assert(events.has_value());
        event.events = *events;
    }

    if (epoll_ctl(epoll_fd_, op_codes.at(ctl), fd, &event) < 0) {
        ThrowLastSystemError();
    }
}

std::size_t Epoller::Wait(const Clock::duration time_out) {
    const auto size {events_.size()};
    assert(size <= std::numeric_limits<int>::max());

    const auto milliseconds {
        std::chrono::duration_cast<std::chrono::milliseconds>(time_out)
            .count()};
    assert(milliseconds <= std::numeric_limits<int>::max());

    if (const auto ready_count {
            epoll_wait(epoll_fd_, events_.data(), size, milliseconds)};
        ready_count >= 0) {
        return ready_count;
    } else if (static_cast<std::errc>(errno) == std::errc::interrupted) {
        // Some signal handlers will interrupt `epoll_wait` and similar system calls on any Linux.
        // This is by design.
        // One typical solution is to explicitly check `errno` for `EINTR`.
        return 0;
    } else {
        ThrowLastSystemError();
    }
}

ThreadPool::ThreadPool(const std::optional<std::size_t> thread_count,
                       log::Logger::Ptr logger) noexcept :
    logger_ {std::move(logger)} {
    if (!logger_) {
        logger_ = log::RootLogger();
    }

    thread_count_ = thread_count.value_or(0);
    if (thread_count_ == 0) {
        thread_count_ = std::thread::hardware_concurrency();
    }
}

ThreadPool::~ThreadPool() noexcept {
    Close();
    for (auto& thread : threads_) {
        assert(thread.joinable());
        thread.join();
    }
}

void ThreadPool::Start() noexcept {
    assert(closed_);
    closed_ = false;
    for (auto i {0}; i != thread_count_; ++i) {
        threads_.emplace_back(&ThreadPool::ExecProc, this);
    }
}

void ThreadPool::Push(Task task) noexcept {
    assert(!closed_);
    const std::lock_guard locker {mtx_};
    tasks_.push_back(std::move(task));
    cond_.notify_one();
}

void ThreadPool::ExecProc() noexcept {
    const auto not_empty_or_closed {[this]() noexcept {
        // Working threads may not have started to wait when closing the thread pool.
        // If a close notification has been sent before they wait,
        // the condition variable will permanently block the thread.
        // So we should check if the thread pool has been closed when waiting.
        return !tasks_.empty() || closed_;
    }};

    while (true) {
        Task task;
        {
            std::unique_lock locker {mtx_};
            cond_.wait(locker, not_empty_or_closed);
            if (!closed_) {
                task = std::move(tasks_.front());
                tasks_.pop_front();
            } else {
                return;
            }
        }

        try {
            assert(task);
            task();
        } catch (const std::exception& err) {
            logger_->Log(
                log::Event::Create(log::Level::Error) << fmt::format(
                    "Exception raised in thread pool's task: {}", err.what()));
        }
    }
}

void ThreadPool::Close() noexcept {
    const std::lock_guard locker {mtx_};
    closed_ = true;
    cond_.notify_all();
}

std::optional<Parameters> ExtractUserMessage(const Request& request) noexcept {
    static constexpr std::string_view user_tag {"user"};
    static constexpr std::string_view msg_tag {"msg"};

    const auto user {request.Post(user_tag).value_or("")};
    const auto msg {request.Post(msg_tag).value_or("")};
    if (!user.empty() && !user.empty()) {
        return Parameters {{user_tag.data(), user.data()},
                           {msg_tag.data(), msg.data()}};
    } else {
        return std::nullopt;
    }
}

std::string_view ContentTypeByFileName(const std::string_view name) noexcept {
    static const std::unordered_map<std::string_view, std::string_view> types {
        {".html", "text/html"},
        {".xml", "text/xml"},
        {".xhtml", "application/xhtml+xml"},
        {".txt", "text/plain"},
        {".rtf", "application/rtf"},
        {".pdf", "application/pdf"},
        {".word", "application/nsword"},
        {".png", "image/png"},
        {".gif", "image/gif"},
        {".jpg", "image/jpeg"},
        {".jpeg", "image/jpeg"},
        {".au", "audio/basic"},
        {".mpeg", "video/mpeg"},
        {".mpg", "video/mpeg"},
        {".avi", "video/x-msvideo"},
        {".gz", "application/x-gzip"},
        {".tar", "application/x-tar"},
        {".css", "text/css"},
        {".js", "text/javascript"},
    };

    const auto extension {
        StringToLower(std::filesystem::path {name}.extension())};
    return types.contains(extension.c_str()) ? types.at(extension.c_str())
                                             : "application/octet-stream";
}

