void Header::Parse(const std::string& line) {
    const std::regex pattern {"^([^:]*): ?(.*)$"};
    std::smatch matches;
    if (std::regex_match(line, matches, pattern)) {
        parser_.headers_.emplace(matches[1], matches[2]);
    } else if (line.empty()) {
        parser_.SetState(std::make_unique<Body>(parser_));
    } else {
        throw std::invalid_argument {
            "There must be an empty line between HTTP headers and the body"};
    }
}

void Body::Parse(const std::string& body) {
    const auto method {parser_.Method()};
    switch (method) {
        case Method::Post: {
            ParsePost(body);
            break;
        }
        default: {
            throw std::invalid_argument {fmt::format(
                "Unsupported HTTP method: '{}'", to_string(method))};
        }
    }

    parser_.SetState(std::make_unique<Finished>(parser_));
}

void Body::ParsePost(const std::string& body) {
    if (const auto content_type {parser_.Header("Content-Type").value_or("")};
        content_type == "application/x-www-form-urlencoded") {
        ParseURLEncodedPost(body);
    } else {
        throw std::invalid_argument {
            fmt::format("Unsupported HTTP content type: '{}'", content_type)};
    }
}

void Body::ParseURLEncodedPost(const std::string& body) {
    auto& post {parser_.post_};
    auto decoded_body {DecodeURLEncodedString(body)};
    std::string_view view {decoded_body};
    std::string key, val;
    std::size_t begin {0}, end {0};
    for (; end < view.size(); ++end) {
        switch (view[end]) {
            case '=': {
                key = view.substr(begin, end - begin);
                begin = end + 1;
                break;
            }
            case '+': {
                decoded_body[end] = ' ';
                break;
            }
            case '&': {
                val = view.substr(begin, end - begin);
                begin = end + 1;
                if (!key.empty()) {
                    post.emplace(std::move(key), std::move(val));
                } else {
                    throw std::invalid_argument {
                        fmt::format("Invalid HTTP POST data: '{}'", body)};
                }

                break;
            }
            default: {
                break;
            }
        }
    }

    // Save the last key-value pair.
    assert(begin <= end);
    val = view.substr(begin, end - begin);
    if (!key.empty() && !post.contains(key) && !val.empty()) {
        post.emplace(std::move(key), std::move(val));
    } else {
        throw std::invalid_argument {
            fmt::format("Invalid HTTP POST data: '{}'", body)};
    }
}

class Request {
public:
    class State;

    Request() noexcept;

    /**
     * @brief Create a parser and parse an HTTP request.
     *
     * @exception std::invalid_argument The HTTP request is invalid.
     */
    explicit Request(Buffer& buf);

    ~Request() noexcept;

    /**
     * @brief Parse an HTTP request.
     *
     * @exception std::invalid_argument The HTTP request is invalid.
     */
    void Parse(Buffer& buf);

    /**
     * @brief Get an HTTP header by its key.
     *
     * @warning The query is case-sensitive.
     */
    std::optional<std::string_view> Header(std::string_view key) const noexcept;

    /**
     * @brief Get an HTTP @p POST variable by its key.
     *
     * @warning The query is case-sensitive.
     */
    std::optional<std::string_view> Post(std::string_view key) const noexcept;

    //! Get the number of HTTP @p POST variables.
    std::size_t PostSize() const noexcept;

    //! Get the HTTP method.
    http::Method Method() const noexcept;

    //! Get the path.
    std::string_view Path() const noexcept;

    //! Get the HTTP version.
    std::string_view Version() const noexcept;

    //! Whether the request keeps alive.
    bool KeepAlive() const noexcept;

private:
    friend class NotStarted;
    friend class Header;
    friend class Body;

    //! Set a new parsing state.
    void SetState(std::unique_ptr<State> state) noexcept;

    //! Clear the cache.
    void Clear() noexcept;

    std::unique_ptr<State> state_;

    http::Method method_ {Method::Get};
    std::string version_;
    std::string path_;

    Parameters headers_;
    Parameters post_;
}

Response::~Response() noexcept {
    Clear();
}

void Response::Clear() noexcept {
    file_.Unmap();
    status_code_ = StatusCode::OK;
    file_path_.clear();
}

Response& Response::SetKeepAlive(const bool set) noexcept {
    keep_alive_ = set;
    return *this;
}

std::optional<MappedReadOnlyFile> Response::Build(Buffer& buf,
                                                  std::filesystem::path file,
                                                  StatusCode& code) noexcept {
    Clear();
    file_path_ = std::move(file);
    status_code_ = StatusCode::OK;
    Build(buf);
    code = status_code_;
    return file_.Data() ? std::optional {std::move(file_)} : std::nullopt;
}

void Response::Build(Buffer& buf, std::filesystem::path file,
                     const Parameters& params, StatusCode& code) noexcept {
    Clear();
    file_path_ = std::move(file);
    status_code_ = StatusCode::OK;
    Build(buf, &params);
    code = status_code_;
}

void Response::Build(Buffer& buf, const StatusCode code,
                     std::string msg) noexcept {
    static constexpr std::string_view http_status_page {"/http-status.html"};
    static constexpr std::string_view status_code_tag {"status-code"};
    static constexpr std::string_view status_tag {"status"};
    static constexpr std::string_view msg_tag {"msg"};

    Clear();
    status_code_ = code;
    file_path_ = http_status_page;

    const Parameters params {
        {status_code_tag.data(), std::to_string(StatusCodeToInteger(status_code_))},
        {status_tag.data(), StatusCodeToMessage(status_code_).data()},
        {msg_tag.data(), std::move(msg)}
    };

    Build(buf, &params);
}

void Response::Build(Buffer& buf, const Parameters* const params) noexcept {
    std::optional<std::string> error_msg;

    try {
        if (!root_dir_.empty()) {
            // The form of an HTTP path is "/path/to/file".
            // Using `relative_path` can get its relative path which is "path/to/file".
            // Otherwise `root_dir_ / file_path_` only returns `file_path_`,
            // because `file_path_` is considered as an absolute path.
            file_.Map(root_dir_ / file_path_.relative_path());
        } else {
            file_.Map(file_path_);
        }
    } catch (const std::exception& err) {
        status_code_ = StatusCode::BadRequest;
        error_msg = err.what();
    }

    AddStatusLine(buf);
    AddHeaders(buf);
    if (!error_msg.has_value()) {
        if (params) {
            AddParamContent(buf, *params);
        } else {
            AddMappedContent(buf);
        }
    } else {
        AddPredefinedErrorContent(buf, *error_msg);
    }
}

void Response::AddStatusLine(Buffer& buf) const noexcept {
    buf.Append(
        fmt::format("HTTP/{} {} {}", version, StatusCodeToInteger(status_code_),
                    StatusCodeToMessage(status_code_)),
        NewLine::CRLF);
}

void Response::AddHeaders(Buffer& buf) const noexcept {
    buf.Append("Connection: ");
    if (keep_alive_) {
        buf.Append("keep-alive", NewLine::CRLF);
        buf.Append("keep-alive: max=6, timeout=120", NewLine::CRLF);
    } else {
        buf.Append("close", NewLine::CRLF);
    }
}

void Response::AddMappedContent(Buffer& buf) noexcept {
    assert(file_.Data());

    buf.Append(fmt::format("Content-type: {}",
                           ContentTypeByFileName(file_path_.c_str())),
               NewLine::CRLF);
    buf.Append(fmt::format("Content-length: {}", file_.Size()), NewLine::CRLF);
    buf.Append(new_line);
}

void Response::AddParamContent(Buffer& buf,
                               const Parameters& params) const noexcept {
    assert(file_.Data());

    buf.Append(fmt::format("Content-type: {}",
                           ContentTypeByFileName(file_path_.c_str())),
               NewLine::CRLF);

    std::string content {reinterpret_cast<const char*>(file_.Data()),
                         file_.Size()};
    for (const auto& [key, val] : params) {
        content = ReplaceAllSubstring(content, HTMLPlaceholder(key), val);
    }

    const auto lines {SplitStringToLines(content)};
    std::size_t length {new_line.length() * (lines.size() - 1)};
    std::for_each(lines.cbegin(), lines.cend(),
                  [&length](const auto& line) { length += line.size(); });

    buf.Append(fmt::format("Content-length: {}", length), NewLine::CRLF);
    buf.Append(new_line);

    for (auto i {0}; i != lines.size(); ++i) {
        if (i != lines.size() - 1) {
            buf.Append(lines[i], NewLine::CRLF);
        } else {
            buf.Append(lines[i]);
        }
    }
}

void Response::AddPredefinedErrorContent(Buffer& buf,
                                         const std::string_view msg) noexcept {
    buf.Append("Content-type: text/html", NewLine::CRLF);

    std::ostringstream ss;
    ss << "<html>" << new_line;
    ss << "<title>ERROR</title>" << new_line;
    ss << "<body>" << new_line;
    ss << fmt::format("<p>{} : {}</p>", StatusCodeToInteger(status_code_),
                      StatusCodeToMessage(status_code_))
       << new_line;
    if (!msg.empty()) {
        ss << fmt::format("<p>{}</p>", msg) << new_line;
    }
    ss << "</body>" << new_line;
    ss << "</html>";

    const auto body {ss.str()};
    buf.Append(fmt::format("Content-length: {}", body.size()), NewLine::CRLF);
    buf.Append(new_line);
    buf.Append(body);
}

class Response {
public:
    /**
     * @brief Create an HTTP response builder.
     *
     * @param root_dir
     * A root directory.
     * If using a relative path to access a file when making response,
     * that path will be relative to the root directory.
     */
    explicit Response(std::filesystem::path root_dir) noexcept;

    ~Response() noexcept;

    Response(const Response&) = delete;

    Response(Response&&) = delete;

    Response& operator=(const Response&) = delete;

    Response& operator=(Response&&) = delete;

    //! Whether the connection should keep alive.
    Response& SetKeepAlive(bool set) noexcept;

    /**
     * @brief Build an HTTP response from a file request.
     *
     * @param[out] buf An output buffer where the response content will be written to.
     * @param file A file path. If it is a relative path, it will be relative to the root directory.
     * @param[out] code The HTTP status code representing the file request.
     * @return
     * A read-only mapped file.  @p std::nullopt if the file request failed.
     * If this method returns a valid mapped file,
     * developers should send file content after sending the response header in the buffer.
     */
    std::optional<MappedReadOnlyFile> Build(Buffer& buf,
                                            std::filesystem::path file,
                                            StatusCode& code) noexcept;

    /**
     * @brief Build an HTTP response from a file request.
     *
     * @param[out] buf An output buffer where the response content will be written to.
     * @param html
     * The path of an HTML page.
     * If it is a relative path, it will be relative to the root directory.
     * @param params
     * HTTP parameters.
     * If @p html contains placeholders, those parameters can be used for replacement.
     * @param[out] code The HTTP status code representing the file request.
     *
     * @warning
     * - This method does not check whether all placeholders in an HTML page have been replaced with parameters.
     * - The parameter name is case-sensitive.
     */
    void Build(Buffer& buf, std::filesystem::path html,
               const Parameters& params, StatusCode& code) noexcept;

    /**
     * @brief Build a response from HTTP status.
     *
     * @param[out] buf An output buffer where the response content will be written to.
     * @param code An HTTP status code.
     * @param msg An optional message.
     */
    void Build(Buffer& buf, StatusCode code, std::string msg = "") noexcept;

private:
    //! Clear settings.
    void Clear() noexcept;

    //! Build an HTTP response from the current settings.
    void Build(Buffer& buf, const Parameters* params = nullptr) noexcept;

    //! Check the file status if there is a file request.
    void CheckFile();

    //! Map the file into memory if there is a valid file request.
    void MapFile();

    //! Add an HTTP status line.
    void AddStatusLine(Buffer& buf) const noexcept;

    //! Add HTTP headers that are not relevant to the content of the response.
    void AddHeaders(Buffer& buf) const noexcept;

    /**
     * @brief Add HTTP headers that are relevant to the mapped read-only file.
     *
     * @note
     * This method does not append file content to the buffer,
     * because the base address of file content will be returned to developers.
     */
    void AddMappedContent(Buffer& buf) noexcept;

    //! Add HTTP headers and generated HTML content from parameters.
    void AddParamContent(Buffer& buf, const Parameters& params) const noexcept;

    //! Add HTTP headers and a predefined error-handling HTML page.
    void AddPredefinedErrorContent(Buffer& buf,
                                   std::string_view msg = "") noexcept;

    std::filesystem::path root_dir_;
    std::filesystem::path file_path_;

    MappedReadOnlyFile file_;

    bool keep_alive_ {false};
    StatusCode status_code_ {StatusCode::OK};
}

std::size_t Null::WriteTo(Buffer& buf) noexcept {
    const auto size {buf.WritableSize()};
    buf.HasWritten(size);
    return size;
}

std::size_t Null::ReadFrom(Buffer& buf) noexcept {
    return buf.RetrieveAll();
}

std::size_t StringStream::WriteTo(Buffer& buf) noexcept {
    std::string str;
    read_ >> str;
    buf.Append(str);
    return str.length();
}

std::size_t StringStream::ReadFrom(Buffer& buf) noexcept {
    const std::string str {buf.RetrieveAllToString()};
    write_ << str;
    return str.length();
}

FileDescriptor::FileDescriptor(const ws::FileDescriptor read,
                               const ws::FileDescriptor write) noexcept :
    read_ {read}, write_ {write} {}

std::size_t FileDescriptor::WriteTo(Buffer& buf) {
    const auto buf_bytes {buf.WritableBytes()};
    std::array<std::byte, 0x10000> ext_bytes;

    // Use an additional buffer to read more data.
    // If the writable size of the input buffer is very small,
    // the remaining data will be placed in the additional buffer,
    // then appended to the input buffer.
    const std::array bufs {
        iovec {.iov_base = buf_bytes.data(), .iov_len = buf_bytes.size_bytes()},
        iovec {.iov_base = ext_bytes.data(), .iov_len = ext_bytes.size()}};

    const auto size {readv(read_, bufs.data(), bufs.size())};
    if (size < 0) {
        ThrowLastSystemError();
    } else if (size <= buf_bytes.size_bytes()) {
        buf.HasWritten(size);
    } else {
        buf.HasWritten(buf_bytes.size_bytes());
        buf.Append({ext_bytes.cbegin(),
                    ext_bytes.cbegin() + (size - buf_bytes.size_bytes())});
    }

    return size;
}

std::size_t FileDescriptor::ReadFrom(Buffer& buf) {
    const auto bytes {buf.ReadableBytes()};
    if (const auto size {write(write_, bytes.data(), bytes.size_bytes())};
        size >= 0) {
        buf.Retrieve(size);
        return size;
    } else {
        ThrowLastSystemError();
    }
}

