    return !(lhs == rhs);
}

bool operator==(const LoggerConfig& lhs, const LoggerConfig& rhs) noexcept {
    return lhs.name == rhs.name && lhs.level == rhs.level
           && lhs.capacity == rhs.capacity && lhs.formatter == rhs.formatter
           && lhs.appenders == rhs.appenders;
}

